#include "stdafx.h"#include "H_Class.h"static SBlockCreate DICHANNEL( "DICHANNEL", SH_DICHANNEL::Create );SH_DICHANNEL::SH_DICHANNEL(): pSlave( NULL ){}#include <HPARM_INIT.h> #include "ParmVarInfo.h"LIST_PARM(SH_DICHANNEL,W_DICHANNEL,50)void SH_DICHANNEL::InitParm(){#include "Blocks/DICHANNEL.h" s_defFlag = SVarInfo::efParam;#include "Blocks/DICHANNEL_P.h"  qsort ( VarInfo, kVarInfo, sizeof ( SVarInfo ), CompVarInfo );}static LPCSTR s_ConPoint = "PV";LPCSTR SH_DICHANNEL::SetDestIO( KBmBase *dest, LPCSTR pszField ){  if( this==dest )    return s_ConPoint;  eVarType type = evtHZ;  BYTE *pV = NULL;  bool b = dest->GetVar( s_ConPoint, &pV, &type );  ASS( b );  ASS( type==evtBool );  pSlave = (BYTE*)pV;  return s_ConPoint;}void SH_DICHANNEL::StepT( SStepCalcParams &dt ){  if( pSlave )    *pSlave = W->PV;  W->PVFL = W->PV;}